  "renderer.wav24Hint": "Передавать настоящий 24-битный WAV. Предлагается по умолчанию; отключается только если проверка обнаружения показывает, что рендерер не заявляет ни audio/L24, ни audio/wav.",
  "renderer.depthCapNotRate": "Внимание: ограничение разрядности не ограничивает частоту дискретизации. Файл 96 кГц/24 бит становится 96 кГц/16 бит — по-прежнему 96 кГц. Если ваш рендерер поддерживает не более 48 кГц, задайте также «Макс. частоту».",
  "renderer.flacAndWavSplitBySource": "«Принудительный WAV» применяется только к источникам не во FLAC (ALAC, AAC…) — он обходит декодер ALAC рендерера. Ваши файлы FLAC по-прежнему передаются как нативный FLAC.",
  "renderer.wav24Unproven": "Ни одна проверка обнаружения ещё не прошла: 24 бит остаётся доступным, но ничто не подтверждает, что это устройство умеет его воспроизводить. Нажмите «Проверить» выше.",
  "renderer.wav24Refused": "Проверка обнаружения ответила: это устройство не заявляет ни audio/L24, ни audio/wav. 24 бит остаётся закрытым — его передача дала бы тишину.",
  "renderer.startDelay": "Задержка запуска",
