  "renderer.fluxContinu": "Непрерывный поток между треками",
  "renderer.fluxContinuHint": "Для плееров, которые плохо стыкуют два трека подряд: идущие подряд треки одного формата отправляются единым потоком WAV без обработки. При первой смене формата возвращается обычная смена треков.",
  "renderer.probeFailed": "Не удалось прочитать возможности рендерера. Сервер не смог определить точную причину.",
  "renderer.probeOffline": "Рендерер сейчас не обнаружен. Убедитесь, что он включён и находится в той же сети.",
  "renderer.probeEmptySink": "Рендерер ответил, но не сообщил пригодных аудиовозможностей. Воспроизведение может всё же работать с автоматическими настройками.",
  "renderer.probeSoapFailed": "Рендерер обнаружен, но запрос возможностей не удался. Повторите попытку; если он уже играет, менять сеть не нужно.",
  "renderer.saveError": "Не удалось сохранить настройку.",
