  "renderer.resetCompat": "Сбросить совместимость",
  "renderer.resetCompatHint": "После отказа этого рендерера Tune запоминает принятую им форму команды и использует её повторно, даже после перезапуска. Сброс заставит следующий трек снова начаться с полной команды.",
  "renderer.resetCompatDone": "Совместимость сброшена: забыто профилей — {n}.",
