  "renderer.resetCompatError": "Не удалось сбросить совместимость.",
  "settings.dlnaCap16bitHint": "Включите, если hi-res (24 бит) на этом рендерере беззвучен, а 16 бит работает (Ruark R3). Перекодирует в 16-битный FLAC вместо прямой отправки 24 бит, которые рендерер не декодирует.",
  "settings.alacPassthroughHint": "Отправлять ALAC на этот рендерер как есть (bit-perfect, без перекодирования во FLAC). Включайте, только если рендерер нативно декодирует ALAC, иначе звука не будет.",
  "settings.aacPassthroughHint": "Отправлять AAC на этот рендерер как есть, вместо перекодирования во FLAC. Источник уже сжат с потерями, поэтому перекодирование не улучшает качество — лишь задерживает первый звук. Включайте, только если рендерер нативно декодирует AAC, иначе звука не будет.",
  "settings.hqplayerHint": "Подключите Tune к HQPlayer для upsampling и аудиофильских фильтров. Порт по умолчанию: 4321 (v4/v5) или 8019 (v6).",
