  "settings.cloudDisconnected": "Выполнен выход из облака",
  "settings.signOutConfirm": "Выйти из аккаунта Mozaiklabs? Этот сервер будет отвязан от аккаунта: его онлайн-копия медиатеки и доступы Tune Circle будут удалены, а функции Premium, предоставляемые аккаунтом, перестанут работать (лицензионный ключ остаётся активным). Потом можно снова войти.",
  "settings.licenseRateLimited": "Слишком много попыток — подождите минуту, прежде чем повторить.",
  "settings.cloudComingSoon": "Облако скоро появится на этом сервере",
  "settings.telemetry": "Телеметрия",
  "settings.telemetryHint": "Отправлять статистику использования для улучшения Tune: идентификатор экземпляра, версия, платформа, размеры медиатеки, подключённые сервисы и модели устройств.",
  "settings.telemetryOffScope": "Её выключение также отключает обмен метаданными сообщества и их загрузку. Проверка лицензии продолжает работать, поэтому Premium никогда не теряется.",
  "settings.communitySync": "Обмен метаданными в сообществе",
  "settings.communitySyncHint": "Участвовать в общем обогащении: сопоставление MusicBrainz, жанры и участники записи (композитор, дирижёр, исполнители), общие для серверов Tune. Анонимно — никогда не ваши файлы.",
  "settings.cloudListens": "Отправлять мои прослушивания в аккаунт",
  "settings.cloudListensHint": "Добавляет прослушивания этого сервера на страницу «Мои прослушивания» вашего аккаунта вместе с другими вашими серверами Tune. Для каждого прослушивания передаются: дата, длительность, непрозрачный идентификатор профиля, название, исполнитель, альбом и, если известны, ISRC и идентификатор MusicBrainz. Никогда — пути к файлам, ваш IP-адрес или названия зон. По умолчанию выключено.",
  "settings.cloudListensLink": "Мои прослушивания на mozaiklabs.fr",
  "settings.cloudListensConsentTitle": "Делиться прослушиваниями с аккаунтом mozaiklabs.fr?",
  "settings.cloudListensConsentIntro": "Tune может добавлять прослушивания этого сервера в ваш аккаунт mozaiklabs.fr. Ничего не отправляется, пока вы не ответите.",
  "settings.cloudListensConsentSentLabel": "Что отправляется:",
  "settings.cloudListensConsentSent": "для каждого прослушивания — дата, длительность, название, исполнитель, альбом, непрозрачный идентификатор профиля и, если известны, идентификаторы ISRC и MusicBrainz.",
  "settings.cloudListensConsentNeverLabel": "Что никогда не отправляется:",
  "settings.cloudListensConsentNever": "пути к вашим файлам, ваш IP-адрес, названия зон и имена профилей.",
  "settings.cloudListensConsentBenefit": "Что вы получаете: страницу «Мои прослушивания», где собраны прослушивания со всех ваших серверов Tune, и прослушивания сообщества.",
  "settings.cloudListensConsentSettingsReminder": "Вы можете передумать в любой момент в разделе Настройки › Система.",
  "settings.cloudListensConsentError": "Не удалось сохранить ваш ответ. Повторите попытку.",
  "settings.cloudListensConsentNo": "Нет",
  "settings.cloudListensConsentYes": "Да, делиться",
  "settings.cloudListensConsentClose": "Закрыть без ответа",
  "settings.communityShare": "Делиться моими оценками и прослушиваниями с сообществом (анонимно)",
  "settings.communityShareHint": "Не связано с «Моими прослушиваниями» и по умолчанию выключено. Ваши оценки альбомов (без комментариев) и прослушивания, полученные аккаунтом ПОСЛЕ включения, входят в публичные анонимные итоги, которые показываются на странице альбома, если наберётся хотя бы три разных человека. Индивидуальные данные никогда не показываются. Выключение сразу убирает ваш вклад.",
  "settings.communityMeasuresReceive": "Получать результаты анализа от сообщества",
  "settings.communityMeasuresReceiveHint": "По умолчанию выключено. Для ваших файлов FLAC сервер запрашивает у mozaiklabs.fr значения ReplayGain, динамического диапазона и акустические отпечатки, уже измеренные на точно таком же сигнале как минимум двумя другими установками. Они заполняют только недостающее: ваши теги и собственные измерения никогда не заменяются. Сайт получает лишь короткий префикс, а не список ваших файлов.",
  "settings.communityMeasuresContribute": "Делиться моими результатами анализа с сообществом",
  "settings.communityMeasuresContributeHint": "По умолчанию выключено. Сервер отправляет на сайт только измерения, которые он сам выполнил для ваших файлов FLAC (ReplayGain, динамический диапазон, акустический отпечаток), с привязкой к сигнатуре их сигнала. Пути, названия, имена файлов и аккаунт не отправляются: сервер идентифицирует себя номером установки. Выключение удаляет то, что было отправлено.",
