  "v2.set.peakMeterHint": "Только отображение — сигнал не меняется. Панель воспроизведения показывает только лампы: два столбчатых индикатора для неё слишком широки.",
  "v2.set.barVu": "Панель воспроизведения с VU-метрами",
  "v2.set.barVuHint": "Только отображение — сигнал не меняется. Две стрелочные шкалы по обе стороны от кнопок управления; они заменяют пиковые лампы и мини-спектр. На узкой панели возвращается обычная.",
  "v2.set.barOnde": "Полоса прогресса в виде волны",
