  "upsampling.eyebrow": "Плагин Premium",
  "upsampling.title": "Апсемплинг",
  "upsampling.lead": "Повышает частоту источника до максимальной частоты, которую принимает ЦАП, с учётом семейства частот (44.1 → 352.8 kHz, 48 → 384 kHz), на локальном выходе. Уровень снижается на 3 dB, а защитный лимитер удерживает редкие оставшиеся пики: клиппинга нет.",
  "upsampling.noZone": "Выберите зону, чтобы настроить её апсемплинг.",
  "upsampling.bitPerfect": "Когда апсемплинг включён, он меняет каждый сэмпл: тракт больше не bit-perfect. Режим PURE всегда его обходит, а поток DoP никогда не передискретизируется.",
  "upsampling.enabled": "Апсемплинг в этой зоне",
  "upsampling.enabledHint": "По умолчанию выключено. Только локальный выход, в общем режиме, на ЦАП с измеренными частотами.",
  "upsampling.filter": "Фильтр",
  "upsampling.filterHint": "Предлагаются только фильтры, которые это устройство выдерживает в реальном времени (с запасом ×3). В скобках — снижение уровня.",
  "upsampling.filterNotAdmitted": "Это устройство не выдерживает этот фильтр в реальном времени: он не будет применён. Выберите другой или измерьте устройство заново.",
  "upsampling.target": "Целевая частота",
  "upsampling.targetHint": "Целое кратное частоты источника, но не выше того, что принимает ЦАП.",
  "upsampling.targetMax": "Максимум ЦАП",
  "upsampling.dither": "Дизеринг",
  "upsampling.ditherHint": "Тот, что у выхода, при уменьшении разрядности: TPDF, без формирования шума.",
  "upsampling.machine": "Тест устройства",
  "upsampling.machineResult": "Фильтров, работающих в реальном времени на этом устройстве: {admitted} из {total}.",
  "upsampling.machineNone": "Ещё не измерено: измерение выполняется при первом сохранении (несколько секунд).",
  "upsampling.remeasure": "Измерить устройство заново",
  "upsampling.nextTrack": "Настройка применяется со следующего трека: уровень никогда не меняется во время трека.",
  "upsampling.save": "Сохранить",
  "upsampling.constraint.premium": "Апсемплинг входит в Tune Premium: ваши настройки сохраняются и будут применены с Premium.",
  "upsampling.constraint.notInstalled": "Установите плагин «Апсемплинг» в разделе «Расширения», чтобы его применить.",
