  "upsampling.constraint.machineTest": "Устройство ещё не измерено: сохраните или измерьте заново, чтобы применить.",
  "upsampling.constraint.zoneNotSupported": "Эта зона не выводит звук через локальный выход устройства: апсемплинг к ней не применяется.",
  "upsampling.constraint.strictBitPerfect": "В этой зоне включён строгий bit-perfect: он запрещает любое преобразование частоты, поэтому апсемплинг не применяется. Отключите его в настройках зоны, чтобы использовать апсемплинг.",
