  "fiche.section.waveform": "Форма волны",
  "fiche.waveform.help": "Чтобы проверить сигнал на максимальных уровнях: пики, клиппинг и компрессию. Клиппинг засчитывается, когда не менее трёх сэмплов подряд остаются на полной шкале: сигнал, скорее всего, был обрезан. Одиночный пик на 0 dBFS (нормализованный трек) не считается. Пик-фактор — это разница между пиком и средним уровнем (невзвешенный RMS): чем он меньше, тем сильнее сжата музыка. Это не PLR по EBU, который измеряется в LUFS.",
